static double[] Softmax(double[] scores, double temperature)
{
    var scaled = scores.Select(s => s / temperature).ToArray();
    var max = scaled.Max();
    var exps = scaled.Select(s => Math.Exp(s - max)).ToArray();
    var sum = exps.Sum();
    return exps.Select(e => e / sum).ToArray();
}

