double[] probabilities = [0.50, 0.25, 0.15, 0.06, 0.04];
const double p = 0.85;

var kept = new List<int>();
double total = 0;
foreach (var (prob, index) in probabilities.Select((v, i) => (v, i)).OrderByDescending(x => x.v))
{
    kept.Add(index);
    total += prob;
    if (total >= p) break;
}
Console.WriteLine($"Top-p {p} keeps {kept.Count} of {probabilities.Length} tokens: {string.Join(", ", kept)}");

